pub struct Logger {
    buf: Vec<String>,
}

impl Logger {
    pub fn new() -> Self { Logger { buf: vec![] } }
    pub fn log(&mut self, msg: &str) {
        let ts = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        self.buf.push(format!("[{}] {}", ts, msg));
    }
    pub fn lines(&self) -> &[String] { &self.buf }
}

fn main() {
    let mut l = Logger::new();
    l.log("hello");
    l.log("world");
    for line in l.lines() {
        println!("{}", line);
    }
}
